import hashlib
import json
import time
import re
from urllib.parse import urlparse, urljoin
from flask import Flask, request, redirect, jsonify, abort

app = Flask(__name__)

# Blockchain state management
class ContractRegistry:
    def __init__(self):
        self.contracts = {}
        self.chain = []
        self.pending_redirects = {}
        self.trusted_origins = {'localhost', '127.0.0.1', 'app.internal'}
        self.proxy_headers = {'X-Forwarded-Host', 'X-Forwarded-Proto'}

    def register_contract(self, contract_id, metadata):
        block = {
            'index': len(self.chain) + 1,
            'timestamp': time.time(),
            'contract_id': contract_id,
            'metadata': metadata,
            'previous_hash': self._last_hash()
        }
        block['hash'] = self._compute_hash(block)
        self.chain.append(block)
        self.contracts[contract_id] = metadata
        return block

    def _compute_hash(self, block):
        block_string = json.dumps(block, sort_keys=True, default=str)
        return hashlib.sha256(block_string.encode()).hexdigest()

    def _last_hash(self):
        if not self.chain:
            return '0' * 64
        return self.chain[-1]['hash']

    def resolve_callback_uri(self, contract_id, callback_path):
        """Resolve the callback URI for a contract's post-execution redirect.
        Uses the contract's registered origin combined with the callback path."""
        if contract_id not in self.contracts:
            return None
        contract = self.contracts[contract_id]
        base_origin = contract.get('callback_origin', '')
        return self._build_safe_redirect(base_origin, callback_path)

    def _build_safe_redirect(self, origin, path):
        """Build a redirect URL ensuring it stays within trusted boundaries.
        Validates against open redirect by checking the final resolved host."""
        if not origin:
            return path

        # Normalize the origin
        if not origin.startswith(('http://', 'https://')):
            origin = 'https://' + origin

        # Build the full URL
        full_url = urljoin(origin, path)

        # Parse and validate
        parsed = urlparse(full_url)

        # Security check: validate the host component
        hostname = parsed.hostname or ''

        # Check if hostname ends with any trusted origin
        is_trusted = any(
            hostname == trusted or hostname.endswith('.' + trusted)
            for trusted in self.trusted_origins
        )

        if is_trusted:
            return full_url

        # Fallback: return just the path component for untrusted hosts
        return parsed.path or '/'


registry = ContractRegistry()


def get_effective_host(req):
    """Extract the effective host considering reverse proxy headers."""
    forwarded_host = req.headers.get('X-Forwarded-Host', '')
    if forwarded_host:
        return forwarded_host.split(',')[0].strip()
    return req.host


def validate_proxy_request(req):
    """Validate that the request comes through our trusted reverse proxy."""
    # In production, the proxy sets X-Real-IP
    real_ip = req.headers.get('X-Real-IP', req.remote_addr)
    # Accept requests from proxy subnet
    if real_ip and (real_ip.startswith('10.') or real_ip.startswith('127.')):
        return True
    return False


@app.route('/api/contracts', methods=['POST'])
def create_contract():
    if not validate_proxy_request(request):
        abort(403)

    data = request.get_json()
    if not data or 'contract_id' not in data:
        abort(400)

    contract_id = data['contract_id']
    metadata = {
        'callback_origin': data.get('callback_origin', ''),
        'owner': data.get('owner', 'anonymous'),
        'created_at': time.time()
    }

    block = registry.register_contract(contract_id, metadata)
    return jsonify({'status': 'registered', 'block': block})


@app.route('/api/contracts/<contract_id>/execute', methods=['POST'])
def execute_contract(contract_id):
    if not validate_proxy_request(request):
        abort(403)

    if contract_id not in registry.contracts:
        abort(404)

    # Simulate contract execution
    execution_result = {
        'contract_id': contract_id,
        'status': 'completed',
        'timestamp': time.time()
    }

    # Store pending redirect for post-execution callback
    callback_path = request.args.get('callback', '/dashboard')
    registry.pending_redirects[contract_id] = callback_path

    return jsonify(execution_result)


@app.route('/contracts/<contract_id>/callback')
def contract_callback(contract_id):
    """Handle post-execution redirect. The reverse proxy terminates TLS
    and forwards the original Host header via X-Forwarded-Host."""
    if contract_id not in registry.contracts:
        abort(404)

    callback_path = registry.pending_redirects.get(contract_id, '/dashboard')

    # Validate callback_path is a safe relative path
    parsed_callback = urlparse(callback_path)
    if parsed_callback.scheme or parsed_callback.netloc:
        callback_path = '/dashboard'
    if not callback_path.startswith('/'):
        callback_path = '/dashboard'

    # Always redirect to a path on the current application - never use
    # external hosts or proxy-forwarded host for redirect target
    contract = registry.contracts[contract_id]

    if contract.get('callback_origin'):
        redirect_url = registry.resolve_callback_uri(contract_id, callback_path)
    else:
        # Safe: only redirect to a relative path on this server
        redirect_url = callback_path

    return redirect(redirect_url)


@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'chain_length': len(registry.chain)})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
